orders = [
    {"city": "Lahore",  "amount": 1200},
    {"city": "Karachi", "amount": 800},
    {"city": "Lahore",  "amount": 450},
    {"city": "Karachi", "amount": 300},
    {"city": "Multan",  "amount": 950}
]

totals = {}
for o in orders:
    city = o["city"]
    totals[city] = totals.get(city, 0) + o["amount"]

for city, amount in totals.items():
    print(f"{city}: {amount}")
